import { createChart, getECModel } from '../../core/utHelper';

function sweep(name: string, makeOption: (v: any) => any, variants: any[], actions: any[]) {
    const problems: string[] = [];
    for (let vi = 0; vi < variants.length; vi++) {
        const chart = createChart({ width: 400, height: 300 });
        try {
            chart.setOption(makeOption(variants[vi]));
        }
        catch (e) {
            problems.push(name + ' variant ' + JSON.stringify(variants[vi]) + ' THROW ' + e);
            chart.dispose();
            continue;
        }
        for (let ai = -1; ai < actions.length; ai++) {
            if (ai >= 0) {
                try {
                    chart.dispatchAction(actions[ai]);
                }
                catch (e) {
                    problems.push(name + ' ' + JSON.stringify(variants[vi]) + ' action THROW ' + e);
                    continue;
                }
            }
            const model = getECModel(chart);
            const gridRect = (model.getComponent('grid', 0) as any).coordinateSystem.getRect();
            const axisModel = model.getComponent('xAxis', 0) as any;
            const axis = axisModel.axis;
            const coords = axis.getTicksCoords().map((t: any) => axis.toGlobalCoord(t.coord));
            const lo = gridRect.x - 1e-6;
            const hi = gridRect.x + gridRect.width + 1e-6;
            for (let i = 0; i < coords.length; i++) {
                if (coords[i] < lo || coords[i] > hi) {
                    problems.push(name + ' ' + JSON.stringify(variants[vi])
                        + ' action=' + ai + ' coord=' + coords[i].toFixed(3)
                        + ' grid=[' + gridRect.x + ',' + (gridRect.x + gridRect.width) + ']'
                        + ' all=' + JSON.stringify(coords.map((c: number) => +c.toFixed(2))));
                    break;
                }
            }
        }
        chart.dispose();
    }
    return problems;
}

describe('zz overflow sweep', function () {
    it('sweep', function () {
        const all: string[] = [];
        const cats: string[] = [];
        const vals: number[] = [];
        for (let i = 0; i < 30; i++) {
            cats.push('c' + i);
            vals.push(i % 7 + 1);
        }

        const variants: any[] = [];
        [true, false].forEach(bg =>
            [undefined, 0, 2, 3, 5, 'auto'].forEach(interval =>
                [true, false].forEach(align =>
                    [true, false].forEach(inverse =>
                        ['filter', 'weakFilter', 'empty', 'none'].forEach(filterMode =>
                            variants.push({ bg, interval, align, inverse, filterMode }))))));

        all.push(...sweep('cat', (v: any) => ({
            animation: false,
            xAxis: {
                type: 'category', data: cats, boundaryGap: v.bg, inverse: v.inverse,
                axisTick: { interval: v.interval, alignWithLabel: v.align }
            },
            yAxis: {},
            dataZoom: [{ type: 'inside', start: 0, end: 100, filterMode: v.filterMode }],
            series: [{ type: 'bar', data: vals }]
        }), variants, [
            { type: 'dataZoom', start: 23, end: 61 },
            { type: 'dataZoom', start: 71, end: 100 },
            { type: 'dataZoom', start: 0, end: 12 },
            { type: 'dataZoom', start: 33.3333, end: 77.7777 },
            { type: 'dataZoom', startValue: 4, endValue: 9 }
        ]));

        console.log('PROBLEMS(' + all.length + '):\n' + all.slice(0, 25).join('\n'));
        expect(true).toBe(true);
    });
});

