import { createChart, getECModel } from '../../core/utHelper';

interface Problem {
    label: string;
    kind: string;
    coord: number;
    lo: number;
    hi: number;
    all: number[];
}

function checkCartesian(chart: any, label: string, out: Problem[]) {
    const model = getECModel(chart);
    const gridComp = model.getComponent('grid', 0) as any;
    if (!gridComp) {
        return;
    }
    const rect = gridComp.coordinateSystem.getRect();
    ['xAxis', 'yAxis'].forEach(function (axisName) {
        let idx = 0;
        for (;; idx++) {
            const axisModel = model.getComponent(axisName, idx) as any;
            if (!axisModel) {
                break;
            }
            const axis = axisModel.axis;
            const horiz = axisName === 'xAxis';
            const gLo = (horiz ? rect.x : rect.y) - 1e-6;
            const gHi = (horiz ? rect.x + rect.width : rect.y + rect.height) + 1e-6;
            const ext = axis.getExtent();
            const eLo = Math.min(axis.toGlobalCoord(ext[0]), axis.toGlobalCoord(ext[1])) - 1e-6;
            const eHi = Math.max(axis.toGlobalCoord(ext[0]), axis.toGlobalCoord(ext[1])) + 1e-6;

            const sets: [string, number[]][] = [];
            sets.push(['tick', axis.getTicksCoords().map((t: any) => axis.toGlobalCoord(t.coord))]);
            sets.push(['splitLine', axis.getTicksCoords({
                tickModel: axisModel.getModel('splitLine'), clamp: true
            }).map((t: any) => axis.toGlobalCoord(t.coord))]);
            sets.push(['splitArea', axis.getTicksCoords({
                tickModel: axisModel.getModel('splitArea'), clamp: true
            }).map((t: any) => axis.toGlobalCoord(t.coord))]);
            const minor: number[] = [];
            axis.getMinorTicksCoords().forEach((g: any[]) =>
                g.forEach((t: any) => minor.push(axis.toGlobalCoord(t.coord))));
            sets.push(['minor', minor]);

            sets.forEach(function (pair) {
                const kind = pair[0];
                const coords = pair[1];
                for (let i = 0; i < coords.length; i++) {
                    const c = coords[i];
                    if (!isFinite(c) || c < gLo || c > gHi || c < eLo || c > eHi) {
                        out.push({
                            label: label + ' ' + axisName + idx,
                            kind: kind + (c < gLo || c > gHi ? '/GRID' : '/EXTENT'),
                            coord: c, lo: gLo, hi: gHi,
                            all: coords.map((x: number) => +x.toFixed(2))
                        });
                        break;
                    }
                }
            });
        }
    });
}

function run(label: string, option: any, actions: any[], out: Problem[]) {
    const chart = createChart({ width: 400, height: 300 });
    try {
        chart.setOption(option);
    }
    catch (e) {
        out.push({ label: label + ' SETOPTION THROW ' + e, kind: 'throw', coord: 0, lo: 0, hi: 0, all: [] });
        chart.dispose();
        return;
    }
    checkCartesian(chart, label + ' [init]', out);
    actions.forEach(function (a, ai) {
        try {
            chart.dispatchAction(a);
        }
        catch (e) {
            out.push({ label: label + ' action' + ai + ' THROW ' + e, kind: 'throw', coord: 0, lo: 0, hi: 0, all: [] });
            return;
        }
        checkCartesian(chart, label + ' [' + JSON.stringify(a) + ']', out);
    });
    chart.dispose();
}

function report(out: Problem[]) {
    const lines = out.map(p => p.kind + ' | ' + p.label + ' | coord=' + (+p.coord.toFixed(3))
        + ' grid=[' + (+p.lo.toFixed(3)) + ',' + (+p.hi.toFixed(3)) + '] all=' + JSON.stringify(p.all));
    console.log('=== PROBLEMS ' + out.length + ' ===\n' + lines.slice(0, 60).join('\n'));
}

